type Locale = 'ru' | 'en' | 'zh';
type Source = 'deterministic_calculator' | 'document_evidence' | 'reviewed_guidance';
type Document = { name: string; text: string; truncated: boolean };
type Turn = { role: 'user' | 'assistant'; text: string };

export type AnswerQualityCase = {
  id: string;
  question: string;
  locale: Locale;
  source: Source;
  required: readonly string[];
  forbidden?: readonly string[];
  documents?: readonly Document[];
  history?: readonly Turn[];
};

type Example = readonly [Locale, string, readonly string[], (readonly string[])?];

function examples(group: string, source: Source, rows: readonly Example[]): AnswerQualityCase[] {
  return rows.map(([locale, question, required, forbidden], index) => ({
    id: group + '-' + (index + 1), question, locale, source, required, forbidden,
  }));
}

