const revisionExamples: AnswerQualityCase[] = revisions.map(([locale,question,oldRate,newRate,line,truncated],i) => {
  const plural=i>=10;
  const name='draft-lot-'+(i+1)+'.docx';
  const head=locale==='ru'?'согласованная цена не подтверждена':locale==='en'?'do not establish an agreed price':'不能证明价格已约定';
  return {
    id:'revision-'+(i+1),locale,question,source:'document_evidence',
    required: plural?['несколько правок цены','уточни пункт']:truncated?[locale==='ru'?'фрагмент неполный':'extract is incomplete',head]:[name,oldRate,newRate,head],
    forbidden:['цена согласована на','Согласованная цена —'],
    documents:[doc(name,trackedNote+'\nПоставка в течение мая.\n'+line+pricePair(oldRate,newRate)+'.\nОбъём указан в приложении.'+
      (plural?'\nЦена второго лота: '+pricePair('15180 ₽/т','15300 ₽/т')+'.':''),truncated)],
  };
});

