const ticketExamples: AnswerQualityCase[] = revisedTickets.map(([locale,question,lot,mass,price,result],i) => {
  const correctedText=locale==='ru'?'Исправленный весовой талон. Партия '+lot+'.\nВес нетто — '+mass+' т.':
    locale==='en'?'Corrected weigh ticket for lot '+lot+'.\nNet weight: '+mass+' t.':'更正地磅单，批次'+lot+'。\n净重'+mass+'吨。';
  const prior=i===8?'P-460':lot;
  const priorText=locale==='ru'?'По партии '+prior+' согласовали цену '+price+' ₽/т.':
    locale==='en'?'For lot '+prior+' I confirmed the price at '+price+' RUB/t.':'批次'+prior+'已确认单价每吨'+price+'卢布。';
  const history: Turn[]=i===7?[{role:'assistant',text:priorText}]:[{role:'user',text:priorText},{role:'assistant',text:'Ранее я мог указать 19999 ₽/т.'}];
  return {
    id:'ticket-'+(i+1),locale,question,source:'document_evidence',
    required:i<7?['scale-'+(i+1)+'.txt',mass,result]:[result],
    forbidden:i<7?['19999']:['Итого —'],
    documents:[doc('scale-'+(i+1)+'.txt',correctedText,i===9)],
    history,
  };
});

